#!/usr/bin/env python3
"""Exact builtin kernel axiom inventory; not a complete source or full gate."""
import json
from pathlib import Path
import re
import sys
PINS = {'Solidity.Backend.InternalFlow.LoopTargetChecks.bad_condition_source': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.bad_loop_source': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.condition_revert_target': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.spin_horizon': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.spin_source': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.divergence_target': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.revert_not_fault': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.divergence_not_revert': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.skipped_source': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.skipped_room': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.skipped_target': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.wrong_capacity': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.wrong_frame': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.assert_refused': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.bytes_refused': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.panic_source': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.bytes_source': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.bytes_not_bare': ['Classical.choice', 'Quot.sound', 'propext']}
NAMES = ['Solidity.Backend.InternalFlow.LoopTargetChecks.bad_condition_source', 'Solidity.Backend.InternalFlow.LoopTargetChecks.bad_loop_source', 'Solidity.Backend.InternalFlow.LoopTargetChecks.condition_revert_target', 'Solidity.Backend.InternalFlow.LoopTargetChecks.spin_horizon', 'Solidity.Backend.InternalFlow.LoopTargetChecks.spin_source', 'Solidity.Backend.InternalFlow.LoopTargetChecks.divergence_target', 'Solidity.Backend.InternalFlow.LoopTargetChecks.revert_not_fault', 'Solidity.Backend.InternalFlow.LoopTargetChecks.divergence_not_revert', 'Solidity.Backend.InternalFlow.LoopTargetChecks.skipped_source', 'Solidity.Backend.InternalFlow.LoopTargetChecks.skipped_room', 'Solidity.Backend.InternalFlow.LoopTargetChecks.skipped_target', 'Solidity.Backend.InternalFlow.LoopTargetChecks.wrong_capacity', 'Solidity.Backend.InternalFlow.LoopTargetChecks.wrong_frame', 'Solidity.Backend.InternalFlow.LoopTargetChecks.assert_refused', 'Solidity.Backend.InternalFlow.LoopTargetChecks.bytes_refused', 'Solidity.Backend.InternalFlow.LoopTargetChecks.panic_source', 'Solidity.Backend.InternalFlow.LoopTargetChecks.bytes_source', 'Solidity.Backend.InternalFlow.LoopTargetChecks.bytes_not_bare']
def check(text):
    if re.search(r"(?:^|\n).*?(?:error:|error\(|sorryAx)",text):
        raise ValueError("Lean diagnostic or untrusted axiom")
    rows = [(n,sorted(x.strip()for x in a.split(',')if x.strip()))
        for n,a in re.findall(r"'([^']+)' (?:depends on axioms:\s*\[([^\]]*)\]|does not depend on any axioms)",text)]
    if rows != [(n,PINS[n])for n in NAMES]:
        raise ValueError("missing, extra, duplicate, reordered or changed axiom report")
    return len(rows)
log = Path(sys.argv[1]).read_text()
print(json.dumps({'status':'pass','reports':check(log)}))
